use crate::adjustment::{AdjustmentParams, apply_adjustments};
use std::sync::Arc;

/// Temporary CPU-bound pixel buffer generated by background worker threads
/// containing raw RGB(A) pixels restored for display preview simulation.
pub struct RawPreview {
    /// Width of the image in pixels.
    pub width: usize,
    /// Height of the image in pixels.
    pub height: usize,
    /// Standard sRGB RGBA interleaved pixel bytes.
    pub rgba: Vec<u8>,
}

/// Cached downscaled source sRGB image kept in memory to avoid repeating disk I/O
/// and Lanczos3 resampling during interactive slider adjustments.
#[derive(Clone)]
pub struct CachedImage {
    pub path: String,
    pub width: usize,
    pub height: usize,
    pub rgba: Arc<Vec<u8>>,
}

/// Cached target CMYK ICC profile bytes kept in memory after validation.
#[derive(Clone)]
pub struct CachedIcc {
    pub path: String,
    pub bytes: Arc<Vec<u8>>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum RenderingIntent {
    Perceptual,
    Relative,
    Saturation,
    Absolute,
}

impl RenderingIntent {
    /// Returns the active slice of intents we process
    pub const ALL: [Self; 4] = [
        Self::Perceptual,
        Self::Relative,
        Self::Saturation,
        Self::Absolute,
    ];

    /// Maps to the lcms2::Intent
    pub fn to_lcms2(self) -> lcms2::Intent {
        match self {
            Self::Perceptual => lcms2::Intent::Perceptual,
            Self::Relative => lcms2::Intent::RelativeColorimetric,
            Self::Saturation => lcms2::Intent::Saturation,
            Self::Absolute => lcms2::Intent::AbsoluteColorimetric,
        }
    }

    /// Maps to the display index in the raw_previews / textures array
    /// [0: Original, 1: Perceptual, 2: Relative, 3: Saturation, 4: Absolute]
    pub fn to_index(self) -> usize {
        match self {
            Self::Perceptual => 1,
            Self::Relative => 2,
            Self::Saturation => 3,
            Self::Absolute => 4,
        }
    }

    /// Creates a RenderingIntent from its display index
    pub fn from_index(index: usize) -> Option<Self> {
        match index {
            1 => Some(Self::Perceptual),
            2 => Some(Self::Relative),
            3 => Some(Self::Saturation),
            4 => Some(Self::Absolute),
            _ => None,
        }
    }

    /// Returns the descriptive label text for the UI buttons
    pub fn label(self) -> &'static str {
        match self {
            Self::Perceptual => "知覚的",
            Self::Relative => "相対的",
            Self::Saturation => "彩度",
            Self::Absolute => "絶対的",
        }
    }

    /// Returns the naming suffix for exported PSD files
    pub fn suffix(self) -> &'static str {
        match self {
            Self::Perceptual => "perceptual",
            Self::Relative => "relative",
            Self::Saturation => "saturation",
            Self::Absolute => "absolute",
        }
    }
}

#[derive(Debug, Clone)]
pub enum AppError {
    ImageOpenError(String),
    ProfileReadError(String),
    ProfileParseError(String),
    NotCmykProfile,
    TransformCreationError(String),
}

impl std::fmt::Display for AppError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::ImageOpenError(msg) => write!(f, "元画像の読み込みに失敗しました: {}", msg),
            Self::ProfileReadError(msg) => {
                write!(f, "カラープロファイルの読み込みに失敗しました: {}", msg)
            }
            Self::ProfileParseError(msg) => {
                write!(f, "カラープロファイルの解析に失敗しました: {}", msg)
            }
            Self::NotCmykProfile => write!(f, "選択されたプロファイルはCMYK色空間ではありません。"),
            Self::TransformCreationError(msg) => write!(f, "変換処理の作成に失敗しました: {}", msg),
        }
    }
}

impl std::error::Error for AppError {}

const PREVIEW_MAX_DIMENSION: u32 = 1600;

/// Builds thread-safe `lcms2::Flags<DisallowCache>` with optional Black Point Compensation (BPC).
#[inline]
pub fn cmm_transform_flags(black_point_compensation: bool) -> lcms2::Flags<lcms2::DisallowCache> {
    if black_point_compensation {
        lcms2::Flags::NO_CACHE | lcms2::Flags::BLACKPOINT_COMPENSATION
    } else {
        lcms2::Flags::NO_CACHE
    }
}

/// Loads and downscales the source image from disk for interactive preview generation.
pub fn load_preview_source(input_path: &str) -> Result<CachedImage, AppError> {
    // Parse the source image from disk
    let img = image::open(input_path).map_err(|e| AppError::ImageOpenError(e.to_string()))?;

    // Downscale for preview performance if the dimension exceeds PREVIEW_MAX_DIMENSION
    let img = if img.width().max(img.height()) > PREVIEW_MAX_DIMENSION {
        img.resize(
            PREVIEW_MAX_DIMENSION,
            PREVIEW_MAX_DIMENSION,
            image::imageops::FilterType::Lanczos3,
        )
    } else {
        img
    };

    let width = img.width() as usize;
    let height = img.height() as usize;
    let rgba_pixels = img.to_rgba8().into_raw();

    Ok(CachedImage {
        path: input_path.to_string(),
        width,
        height,
        rgba: Arc::new(rgba_pixels),
    })
}

/// Reads and validates a target CMYK ICC color profile from disk.
pub fn load_cmyk_icc(icc_path: &str) -> Result<CachedIcc, AppError> {
    let icc_data =
        std::fs::read(icc_path).map_err(|e| AppError::ProfileReadError(e.to_string()))?;

    let cmyk_profile = lcms2::Profile::new_icc(&icc_data)
        .map_err(|e| AppError::ProfileParseError(e.to_string()))?;

    if cmyk_profile.color_space() != lcms2::ColorSpaceSignature::CmykData {
        return Err(AppError::NotCmykProfile);
    }

    Ok(CachedIcc {
        path: icc_path.to_string(),
        bytes: Arc::new(icc_data),
    })
}

/// Applies image adjustments in sRGB space and generates soft-proofed CMYK previews
/// for the requested subset of rendering intents using cached source buffers.
pub fn render_intent_previews(
    source: &CachedImage,
    icc: &CachedIcc,
    adjustments: AdjustmentParams,
    black_point_compensation: bool,
    intents: &[RenderingIntent],
) -> Result<Vec<(RenderingIntent, RawPreview)>, AppError> {
    let width = source.width;
    let height = source.height;

    // Apply tone and HSV adjustments prior to forward RGB -> CMYK ICC translation
    let adjusted_rgba = apply_adjustments(&source.rgba, width, height, adjustments);

    let cmyk_profile = lcms2::Profile::new_icc(&icc.bytes)
        .map_err(|e| AppError::ProfileParseError(e.to_string()))?;

    if cmyk_profile.color_space() != lcms2::ColorSpaceSignature::CmykData {
        return Err(AppError::NotCmykProfile);
    }

    // Instantiate standard source sRGB profile template
    let srgb_profile = lcms2::Profile::new_srgb();

    // Step 2 (shared across all forward intents):
    // Convert computed CMYK matrix back to RGBA to simulate print gamut on screen.
    //
    // CMYK back to sRGB proofing transform enforces RelativeColorimetric regardless of the
    // forward intent. If AbsoluteColorimetric were used, it would simulate the physical substrate
    // color (paper white), rendering screen whites muddy gray.
    // RelativeColorimetric maps paper white to display white (255), matching professional proofing
    // tools like Krita.
    // `new_flags_context` with `Flags::NO_CACHE` produces a thread-safe `Sync` Transform.
    let t_cmyk_to_rgb = lcms2::Transform::new_flags_context(
        lcms2::GlobalContext::new(),
        &cmyk_profile,
        lcms2::PixelFormat::CMYK_8,
        &srgb_profile,
        lcms2::PixelFormat::RGBA_8,
        lcms2::Intent::RelativeColorimetric, // Enforce Relative Colorimetric for proofing simulation
        lcms2::Flags::NO_CACHE,
    )
    .map_err(|e| AppError::TransformCreationError(e.to_string()))?;

    let forward_flags = cmm_transform_flags(black_point_compensation);
    let mut rendered = Vec::with_capacity(intents.len());

    for &intent_enum in intents {
        let intent = intent_enum.to_lcms2();

        // Step 1: Initialize thread-safe CMM Transform to convert standard RGBA to custom target CMYK
        let t_rgb_to_cmyk = lcms2::Transform::new_flags_context(
            lcms2::GlobalContext::new(),
            &srgb_profile,
            lcms2::PixelFormat::RGBA_8,
            &cmyk_profile,
            lcms2::PixelFormat::CMYK_8,
            intent,
            forward_flags,
        )
        .map_err(|e| AppError::TransformCreationError(e.to_string()))?;

        let preview_rgba = soft_proof_pixels(
            &adjusted_rgba,
            width * height,
            &t_rgb_to_cmyk,
            &t_cmyk_to_rgb,
        );

        rendered.push((
            intent_enum,
            RawPreview {
                width,
                height,
                rgba: preview_rgba,
            },
        ));
    }

    Ok(rendered)
}

/// Executes forward (sRGB -> CMYK) and proofing (CMYK -> sRGB) transforms across CPU cores
/// in cache-friendly chunks while restoring opaque alpha bytes (`255`).
fn soft_proof_pixels(
    src_rgba: &[u8],
    pixel_count: usize,
    t_rgb_to_cmyk: &lcms2::Transform<u8, u8, lcms2::GlobalContext, lcms2::DisallowCache>,
    t_cmyk_to_rgb: &lcms2::Transform<u8, u8, lcms2::GlobalContext, lcms2::DisallowCache>,
) -> Vec<u8> {
    let mut preview_rgba = vec![0u8; pixel_count * 4];
    let parallelism = std::thread::available_parallelism()
        .map(|n| n.get())
        .unwrap_or(1);

    let process_chunk = |src_chunk: &[u8], dst_chunk: &mut [u8]| {
        const L2_TILE_BYTES: usize = 16_384 * 4;
        let mut cmyk_tile = vec![0u8; L2_TILE_BYTES.min(src_chunk.len())];

        for (s_tile, d_tile) in src_chunk
            .chunks(L2_TILE_BYTES)
            .zip(dst_chunk.chunks_mut(L2_TILE_BYTES))
        {
            let cmyk_slice = &mut cmyk_tile[..s_tile.len()];
            t_rgb_to_cmyk.transform_pixels(s_tile, cmyk_slice);
            t_cmyk_to_rgb.transform_pixels(cmyk_slice, d_tile);

            // CMYK lacks an alpha channel. The conversion back to sRGB sets alpha to 0, which would
            // render the image invisible in egui. We restore the alpha byte to 255 (100% opaque).
            for px in d_tile.chunks_exact_mut(4) {
                px[3] = 255;
            }
        }
    };

    if parallelism > 1 && pixel_count >= 32_768 {
        let pixels_per_worker = pixel_count.div_ceil(parallelism);
        let bytes_per_worker = pixels_per_worker * 4;

        std::thread::scope(|s| {
            for (src_chunk, dst_chunk) in src_rgba
                .chunks(bytes_per_worker)
                .zip(preview_rgba.chunks_mut(bytes_per_worker))
            {
                s.spawn(move || {
                    process_chunk(src_chunk, dst_chunk);
                });
            }
        });
    } else {
        process_chunk(src_rgba, &mut preview_rgba);
    }

    preview_rgba
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_render_intent_previews_with_japan_color_icc() {
        let icc = load_cmyk_icc("JapanColor2001Coated.icc")
            .expect("JapanColor2001Coated.icc should load and validate as CMYK");
        let src = CachedImage {
            path: "synthetic.png".to_string(),
            width: 32,
            height: 32,
            rgba: Arc::new(vec![180, 90, 220, 255].repeat(32 * 32)),
        };

        let base = render_intent_previews(
            &src,
            &icc,
            AdjustmentParams::default(),
            true,
            &[RenderingIntent::Perceptual],
        )
        .expect("Base soft-proof preview should succeed");

        let adjusted = render_intent_previews(
            &src,
            &icc,
            AdjustmentParams {
                hue: -20,
                saturation: 30,
                value: 10,
                contrast: 15,
                highlights: -10,
                shadows: 25,
            },
            true,
            &RenderingIntent::ALL,
        )
        .expect("Adjusted soft-proof preview across all intents should succeed");

        assert_eq!(base.len(), 1);
        assert_eq!(adjusted.len(), 4);
        assert_ne!(base[0].1.rgba, adjusted[0].1.rgba);
        // Alpha must be restored to 255 on all pixels
        assert!(adjusted[0].1.rgba.chunks_exact(4).all(|px| px[3] == 255));
    }

    #[test]
    fn test_black_point_compensation_flag_on_relative_intent() {
        let icc = load_cmyk_icc("JapanColor2001Coated.icc")
            .expect("JapanColor2001Coated.icc should load and validate as CMYK");
        // Deep shadow ramp where BPC makes a measurable difference under Relative Colorimetric
        let mut pixels = Vec::with_capacity(64 * 4);
        for v in 0..64u8 {
            pixels.extend_from_slice(&[v, v, v, 255]);
        }
        let src = CachedImage {
            path: "shadow_ramp.png".to_string(),
            width: 8,
            height: 8,
            rgba: Arc::new(pixels),
        };

        let with_bpc = render_intent_previews(
            &src,
            &icc,
            AdjustmentParams::default(),
            true,
            &[RenderingIntent::Relative],
        )
        .expect("Relative preview with BPC should succeed");

        let without_bpc = render_intent_previews(
            &src,
            &icc,
            AdjustmentParams::default(),
            false,
            &[RenderingIntent::Relative],
        )
        .expect("Relative preview without BPC should succeed");

        assert_ne!(
            with_bpc[0].1.rgba, without_bpc[0].1.rgba,
            "Black Point Compensation should alter deep shadow mapping under Relative Colorimetric"
        );
    }
}
